command:
// ==========================================
// ⚙️ LUNAS WIRKUNG: FLEISCHPUPPE (V13 Ready - Design-Korrektur)
// ==========================================

(async () => {
    // Framework laden
    const fwMacro = await fromUuid("Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn");
    if (fwMacro) await fwMacro.execute();
    const DSK_FW = globalThis.DSK || DSK;

    const gabenName = "Fleischpuppe (Zerzal)";
    const ahne = "zerzal";
    const finalEffektName = `${gabenName}`;

    // Effekt-Ende registrieren
    if (DSK_FW.EffektEnde) {
        DSK_FW.EffektEnde.Register(
            "zerzalFleischpuppe", 
            finalEffektName, 
            "Die Besetzung endet, und das Zerzalkind erhält die Kontrolle über seinen Körper zurück – man nimmt die wahre Gestalt wieder an."
        );
    }

    // --- 1. AKTEUR & QS ---
    const casterActor = canvas.tokens.controlled[0]?.actor || game.user.character;
    if (!casterActor) return ui.notifications.warn("Kein Wirkender gefunden!");

    const qs = casterActor.getFlag("world", "letzteGabenQS") || 1;
    const alteMessageId = casterActor.getFlag("world", "letzteGabenMessageId");

    // --- 2. BERECHNUNGEN (Dünn) ---
    const dauerMinuten = qs * 30;
    const thinStyle = 'style="font-weight: 300; font-size: 0.9em; opacity: 0.8;"';
    const dauerCalc = `<span ${thinStyle}>(${qs} QS x 30 Min.)</span>`;
    const basisBeschreibung = `Das Zerzalkind leiht dem Geist seinen Körper. Der Geist kann ihn lenken. Das Zerzalkind kann zwar weiterhin sehen und hören, aber nicht eingreifen.`;

    // --- 3. WESEN-CHECK ---
    const istGueltig = DSK_FW.Effekt.CheckTarget(casterActor, "lebewesen") || DSK_FW.Effekt.CheckTarget(casterActor, "erwachte");
    const isGeistOderUntot = DSK_FW.Effekt.CheckTarget(casterActor, "geist") || DSK_FW.Effekt.CheckTarget(casterActor, "untot");

    let erfolg = false;
    let fehlerGrund = "";

    if (!istGueltig || isGeistOderUntot) {
        fehlerGrund = "Kein Mensch, Tier oder Erwachter";
    } else {
        // --- 4. EFFEKT ANWENDEN ---
        try {
            let alterEffekt = casterActor.effects.find(e => e.name === finalEffektName);
            if (alterEffekt) await alterEffekt.delete();

            await DSK_FW.Effekt.Anwenden({
                name: finalEffektName,
                ahne: ahne,
                beschreibung: basisBeschreibung,
                gabeZiel: "erwachte",
                qs: qs,
                ziel: casterActor,
                flags: { dsk: { casterUuid: casterActor.uuid } }
            });

            const eff = casterActor.effects.find(e => e.name === finalEffektName);
            if (eff) {
                await eff.update({ "duration.seconds": dauerMinuten * 60 });
                erfolg = true;
            }
        } catch (e) {
            console.warn("Fehler bei Fleischpuppe:", e);
            fehlerGrund = "Framework-Fehler";
        }
    }

    // --- 5. FLAG-CLEANUP (Nur bei Erfolg) ---
    if (erfolg) {
        await casterActor.unsetFlag("world", "letzteGabenQS");
        await casterActor.unsetFlag("world", "letzteGabenMessageId");
    }

    // --- 6. CHAT-KARTE (Update oder Neu) ---
    let ownerIds = new Set(game.users.filter(u => u.isGM).map(u => u.id));
    Object.entries(casterActor.ownership || {}).filter(([id, lvl]) => lvl === 3).forEach(([id]) => ownerIds.add(id));

    // Design der Liste: Dünn, schwarz, Pfoten-Icon (dsklist)
    const statusHtml = erfolg 
        ? `<div style="margin-top: 10px; margin-bottom: 10px;">
               <p style="margin-bottom: 5px; font-weight:bold;">Besetzung aktiv:</p>
               <ul class="dsklist" style="margin-top:0; font-weight:normal; color: #000;">
                   <li>${casterActor.name}</li>
               </ul>
           </div>`
        : `<div style="margin-top: 10px; margin-bottom: 10px;">
               <p style="margin-bottom: 5px;"><span style="color:#B30000; font-weight:bold;">Fehlschlag</span></p>
               <ul class="dsklist" style="margin-top:0; font-weight:normal; color: #000;">
                   <li>${casterActor.name} (${fehlerGrund})</li>
               </ul>
           </div>`;

    const cardContent = `
        <div style="font-family: 'Signika', sans-serif;">
            ${DSK_FW.UI.Header(gabenName, DSK_FW.Symbol(ahne))}
            <div class="dskbox2" style="margin-top:10px;">
                <p><b>Gabenwirkung:</b></p>
                <p style="margin-top:0;">${basisBeschreibung}</p>
                <hr>
                ${statusHtml}
                <hr>
                <p style="text-align:center;">
                    <b>Wirkungsdauer:</b> ${dauerMinuten} Min. ${dauerCalc}
                </p>
            </div>
        </div>
    `;

    // Aktualisieren oder neu senden
    let msg = alteMessageId ? game.messages.get(alteMessageId) : null;
    if (msg) {
        await msg.update({ content: cardContent });
    } else {
        const neueMsg = await ChatMessage.create({
            speaker: { alias: "System" },
            whisper: Array.from(ownerIds).filter(id => game.users.get(id)),
            content: cardContent
        });
        if (neueMsg && !erfolg) {
            await casterActor.setFlag("world", "letzteGabenMessageId", neueMsg.id);
        }
    }
})();
